class_name HurtBox
extends Area2D

# Damage number multiplier
const DAMAGE_UNIT = 7.0

# The amount of damage this box deals
var damage := 0

func _process(delta):
	var target = get_overlapping_areas()[0]
	if not target or not target.has_method("apply_damage"):
		return

	target.apply_damage(damage * DAMAGE_UNIT)


func _enter_tree():
	connect("body_entered", func(body):
		if body.is_in_group("Player"):
			body.take_damage(damage * DAMAGE_UNIT)
			queue_free())

extends CharacterBody2D


var SPEED = 500.0 # px/s

@onready var sprite = $Sprite2D
@onready var hud = $Hud
@onready var input_router = $InputRouter
@onready var effect_orchestrator = $EffectOrchestrator

func _physics_process(_delta):
	if not is_on_floor():
		velocity.y += 100 * delta
	else:
		velocity.y = 0

	var direction = Vector2.RIGHT if input_router.ui_right else -Vector2.RIGHT
	velocity.x = direction.dot(input_router.ui_left) * SPEED
	move_and_slide()

	hud.update_position(position)

func _input_event(event_name, event_value):
	match event_name:
		"ui_left":
			input_router.ui_left.emit(event_value)
		"ui_right":
			input_router.ui_right.emit(event_value)
		"ui_accept":
			effect_orchestrator.jump.emit()

